export async function applyCatalogGuides(sql) {
  const desired = catalogGuides.map(({id,summary,description,usageSteps,expectedSummary,expectedDescription}) => ({
    id,summary,description,usage_steps:usageSteps,expected_summary:expectedSummary,expected_description:expectedDescription,
  }));
  // Update existing, public rows only. An intervening administrator edit wins.
  // No inserts, publication changes, deletion-marker changes, attachment changes, or ordering changes.
  return sql`
    WITH desired AS (
      SELECT * FROM jsonb_to_recordset(${JSON.stringify(desired)}::jsonb)
      AS d(id text,summary text,description text,usage_steps jsonb,expected_summary text,expected_description text)
    ), changed AS (
      UPDATE programs p SET summary=d.summary,description=d.description,usage_steps=d.usage_steps,updated_at=NOW()
      FROM desired d WHERE p.id=d.id AND p.is_published=TRUE AND p.deleted_at IS NULL
        AND p.summary=d.expected_summary AND p.description=d.expected_description AND p.usage_steps='[]'::jsonb
      RETURNING p.id
    )
    SELECT d.id, CASE WHEN c.id IS NOT NULL THEN 'updated'
      WHEN p.id IS NULL OR p.deleted_at IS NOT NULL OR NOT p.is_published THEN 'unavailable'
      WHEN p.summary=d.summary AND p.description=d.description AND p.usage_steps=d.usage_steps THEN 'current'
      ELSE 'administrator-edit-preserved' END AS status
    FROM desired d LEFT JOIN programs p ON p.id=d.id LEFT JOIN changed c ON c.id=d.id ORDER BY d.id
  `;
}

const invoked = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invoked) {
  if (process.argv.length !== 3 || process.argv[2] !== '--apply-guides-20261016') {
    console.log('Catalog guide update skipped; explicit --apply-guides-20261016 is required.');
  } else if (process.env.VERCEL_ENV !== 'production') {
    console.log('Catalog guide update deferred to production.');
  } else {
    const { neon } = await import('@neondatabase/serverless');
    if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL is required.');
    const report = await applyCatalogGuides(neon(process.env.DATABASE_URL));
    for (const {id,status} of report) console.log('Catalog guide:',id,status);
  }
}
